INSERT INTO brands VALUES ('00000000-0000-4000-8000-000000000010'),('00000000-0000-4000-8000-000000000020');
INSERT INTO clients VALUES ('00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000010','Cliente A'),('00000000-0000-4000-8000-000000000012','00000000-0000-4000-8000-000000000010','Cliente B');
SELECT set_config('test.user','00000000-0000-4000-8000-000000000001',false);
DO $$
DECLARE stages jsonb:='[{"key":"idea","label":"Entrada","color":"muted","is_terminal":false,"hide_in_portal":true,"enables_approval_link":false,"sla_hours":24},{"key":"done","label":"Concluído","color":"emerald","is_terminal":true,"hide_in_portal":false,"enables_approval_link":true,"sla_hours":null}]';
 preview jsonb; result jsonb; pipe uuid; first_stage uuid; extra uuid; op uuid:=gen_random_uuid(); rejected boolean;
BEGIN
 IF has_function_privilege('anon','public.production_stages_apply(uuid,jsonb,boolean,jsonb,text,uuid)','EXECUTE') OR has_table_privilege('anon','public.production_stage_defaults','SELECT') OR has_table_privilege('authenticated','public.production_stage_defaults','UPDATE') THEN RAISE EXCEPTION 'unsafe grants'; END IF;
 preview:=production_stages_preview('00000000-0000-4000-8000-000000000010',stages,false,'{}');
 IF jsonb_array_length(preview->'clients')<>2 OR EXISTS(SELECT 1 FROM production_stage_defaults) OR EXISTS(SELECT 1 FROM content_pipelines) THEN RAISE EXCEPTION 'preview wrote data'; END IF;
 result:=production_stages_apply('00000000-0000-4000-8000-000000000010',stages,false,'{}',preview->>'fingerprint',op);
 IF (result->>'clients')::int<>2 OR (SELECT count(*) FROM content_pipeline_stages)<>4 THEN RAISE EXCEPTION 'apply incomplete'; END IF;
 IF production_stages_apply('00000000-0000-4000-8000-000000000010',stages,false,'{}',preview->>'fingerprint',op)<>result OR (SELECT count(*) FROM production_stage_applications)<>1 THEN RAISE EXCEPTION 'replay duplicated'; END IF;
 SELECT id INTO pipe FROM content_pipelines WHERE client_id='00000000-0000-4000-8000-000000000011';
 SELECT id INTO first_stage FROM content_pipeline_stages WHERE pipeline_id=pipe AND key='idea';
 INSERT INTO posts(pipeline_id,stage_id,copy,review_status) VALUES(pipe,first_stage,'Preservar texto','pending');
 stages:=jsonb_set(stages,'{0,label}','"Renomeada"');
 preview:=production_stages_preview('00000000-0000-4000-8000-000000000010',stages,true,'{}');
 PERFORM production_stages_apply('00000000-0000-4000-8000-000000000010',stages,true,'{}',preview->>'fingerprint',gen_random_uuid());
 IF NOT EXISTS(SELECT 1 FROM content_pipeline_stages WHERE id=first_stage AND label='Renomeada') OR NOT EXISTS(SELECT 1 FROM posts WHERE stage_id=first_stage AND copy='Preservar texto' AND review_status='pending') THEN RAISE EXCEPTION 'rename moved/changed piece'; END IF;
 -- Fase C: conclusão usa a mesma etapa, sem alterar peças ou aprovações.
 stages:=jsonb_set(stages,'{0,is_terminal}','true');
 PERFORM production_stages_save('00000000-0000-4000-8000-000000000010',stages);
 IF NOT (SELECT (stages->0->>'is_terminal')::boolean FROM production_stage_defaults WHERE brand_id='00000000-0000-4000-8000-000000000010') OR (SELECT is_terminal FROM content_pipeline_stages WHERE id=first_stage) THEN RAISE EXCEPTION 'completion save changed existing pipeline'; END IF;
 preview:=production_stages_preview('00000000-0000-4000-8000-000000000010',stages,true,'{}');
 PERFORM production_stages_apply('00000000-0000-4000-8000-000000000010',stages,true,'{}',preview->>'fingerprint',gen_random_uuid());
 IF NOT (SELECT is_terminal FROM content_pipeline_stages WHERE id=first_stage) OR NOT EXISTS(SELECT 1 FROM posts WHERE stage_id=first_stage AND copy='Preservar texto' AND review_status='pending') THEN RAISE EXCEPTION 'completion application lost stage or approval'; END IF;
 stages:=jsonb_set(stages,'{0,is_terminal}','false');
 preview:=production_stages_preview('00000000-0000-4000-8000-000000000010',stages,true,'{}');
 PERFORM production_stages_apply('00000000-0000-4000-8000-000000000010',stages,true,'{}',preview->>'fingerprint',gen_random_uuid());
 IF (SELECT is_terminal FROM content_pipeline_stages WHERE id=first_stage) THEN RAISE EXCEPTION 'completion cannot be unset'; END IF;
 INSERT INTO content_pipeline_stages(pipeline_id,key,label,color,position) VALUES(pipe,'extra','Especial','muted',2048) RETURNING id INTO extra;
 INSERT INTO posts(pipeline_id,stage_id,copy,review_status) VALUES(pipe,extra,'Peça ativa','pending'),(pipe,extra,'Peça na lixeira','approved');
 UPDATE posts SET deleted_at=now() WHERE copy='Peça na lixeira';
 IF (SELECT follows_brand_default FROM content_pipelines WHERE id=pipe) THEN RAISE EXCEPTION 'local edit not exception'; END IF;
 preview:=production_stages_preview('00000000-0000-4000-8000-000000000010',stages,true,'{}');
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(preview->'clients') c WHERE c->>'pipelineId'=pipe::text AND (c->>'skipped')::boolean) THEN RAISE EXCEPTION 'exception not preserved'; END IF;
 preview:=production_stages_preview('00000000-0000-4000-8000-000000000010',stages,false,'{}');
 IF NOT (preview->>'blocked')::boolean THEN RAISE EXCEPTION 'missing mapping accepted'; END IF;
 rejected:=false;
 BEGIN PERFORM production_stages_apply('00000000-0000-4000-8000-000000000010',stages,false,'{}',preview->>'fingerprint',gen_random_uuid()); EXCEPTION WHEN OTHERS THEN IF SQLERRM='production_destination_required' THEN rejected:=true; ELSE RAISE; END IF; END;
 IF NOT rejected OR NOT EXISTS(SELECT 1 FROM content_pipeline_stages WHERE id=extra) THEN RAISE EXCEPTION 'occupied stage removed'; END IF;
 result:=production_stages_apply('00000000-0000-4000-8000-000000000010',stages,false,jsonb_build_object(extra::text,'idea'),preview->>'fingerprint',gen_random_uuid());
 IF (result->>'movedPosts')::int<>2 OR EXISTS(SELECT 1 FROM content_pipeline_stages WHERE id=extra) OR (SELECT count(*) FROM posts WHERE stage_id=first_stage)<>3 THEN RAISE EXCEPTION 'mapping lost pieces'; END IF;
 preview:=production_stages_preview('00000000-0000-4000-8000-000000000010',stages,false,'{}');
 INSERT INTO posts(pipeline_id,stage_id,copy) VALUES(pipe,first_stage,'Concorrente');
 rejected:=false;
 BEGIN PERFORM production_stages_apply('00000000-0000-4000-8000-000000000010',stages,false,'{}',preview->>'fingerprint',gen_random_uuid()); EXCEPTION WHEN OTHERS THEN IF SQLERRM='production_preview_stale' THEN rejected:=true; ELSE RAISE; END IF; END;
 IF NOT rejected THEN RAISE EXCEPTION 'stale preview accepted'; END IF;
 INSERT INTO clients VALUES ('00000000-0000-4000-8000-000000000013','00000000-0000-4000-8000-000000000010','Novo cliente');
 IF NOT EXISTS(SELECT 1 FROM content_pipelines p JOIN content_pipeline_stages s ON s.pipeline_id=p.id WHERE p.client_id='00000000-0000-4000-8000-000000000013' AND p.follows_brand_default AND s.label='Renomeada' AND s.sla_hours=24) THEN RAISE EXCEPTION 'new client missing default'; END IF;
 PERFORM set_config('test.user','00000000-0000-4000-8000-000000000002',true);
 rejected:=false;
 BEGIN PERFORM production_stages_save('00000000-0000-4000-8000-000000000010',stages); EXCEPTION WHEN OTHERS THEN IF SQLERRM='production_stages_forbidden' THEN rejected:=true; ELSE RAISE; END IF; END;
 IF NOT rejected THEN RAISE EXCEPTION 'manager wrote default'; END IF;
 PERFORM set_config('test.user','00000000-0000-4000-8000-000000000001',true);
 rejected:=false;
 BEGIN PERFORM production_stages_preview('00000000-0000-4000-8000-000000000020',stages,false,'{}'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='production_stages_forbidden' THEN rejected:=true; ELSE RAISE; END IF; END;
 IF NOT rejected THEN RAISE EXCEPTION 'cross-workspace access'; END IF;
END; $$;